INSERT INTO sq_items (code, category_id, title, points, requirement, sort_order) VALUES ('1_1', 1, '표준류 작성 및 준수상태', 20, '- 표준류(관리계획서, 작업표준서, 설비일상점검표 등)와 실제공정 일치성 확인[관리 분담 등]
    - 고객과 협의된 검사협정서/검사기준서 기준과 실제 업무절차 일치성
    - 공정 FMEA작성 및 주요 품질 문서 내용과 연계상태 확인
    - 주요 표준류(작업표준서 등) 현장내 게시 상태
    - 관리계획서 및 현장내 표준류 중요공정/안전 보안공정 식별표시관리
    - 신규/임시작업자 공정투입전 업무 R&R 명확화, 단계별 작업표준서 게시 및 전문용어 사용지양
    - 공정내 사용되는 설비 및 부자재등은 사전 검증을 통해 표준류 반영되어야 하며 미승인 설비 및 부자재 사용 금지
       ex) 조립성 확보를 위한 미승인 열풍기 및 윤활재 사용등', 0);
INSERT INTO sq_items (code, category_id, title, points, requirement, sort_order) VALUES ('1_2', 1, '설비 가동중단(계획/비계획)후 재가동시 업무처리 절차 수립 및 준수상태', 20, '- 설비 가동중단 발생시 설비점검 절차 수립 및 준수상태
      ※ 계획 : 가동중단 시간별/사유별 점검절차 수립 및 이행
         비계획 : 이상발생 가동중단 발생시 설비 점검 지침, 생산중인 제품에 대한 품질보증 업무절차 수립 및 이행
    - 설비중단/이상 발생시(툴교환 포함) 직전 생산품 이상유무 검사 및 설비이상 조치후 초품 이상유무 검사 및 기록관리
       (설비중단/이상 발생시 또는 설비이상 조치중 생산부품 불량으로 폐기 및 수량 이력관리)
    - 비계획 가동중단 발생시 전/후 생산제품에 대한 LOT 구분 관리방안 수립 및 식별관리 실시', 1);
INSERT INTO sq_items (code, category_id, title, points, requirement, sort_order) VALUES ('1_3', 1, '외국인 배치 운영공정 현지어 번역/게시된 표준류 반영상태', 10, '- 작업표준서, 설비일상점검 기준표, 작업일보 등 외국인 배치공정 표준류 현지어 번역 게시상태
      : 부적합 처리절차 및 중요 품질문제 개선 사례등 품질의식 강화목적 표준류 번역 게시 (추가 관리시 우수)
      ※ 해당공정 외국인작업자 주요 표준류 교육 및 내용 숙지 시 현지어 번역게시 불필요(현장확인 필요)', 2);
INSERT INTO sq_items (code, category_id, title, points, requirement, sort_order) VALUES ('1_4', 1, '품질관리 취약 시간대 관리기준 수립 및 관리상태 (주말특근 및 비지정 작업자 투입시포함)', 20, '- 교대 작업시 일상점검, 자주검사 및 순회검사 관리기준 수립 및 관리상태
    - 교대 작업시 공정 Issue 사항 전달 여부
      ※ 초/종품 검사는 필수, 중품은 선택사항으로 자율적 기준 수립필요, 중품검사 미진행도 가능,
          단, 생산LOT가 장기적일경우 최소 1회/shift검사 진행 필요
      ※ 인원 부족으로 야간 검사요원 미 투입 시 야간 생산품 검증 프로세스 수립
          (야간 작업 초종 생산품 익일 주간 검사인원 출근시 검사 등)', 3);
INSERT INTO sq_items (code, category_id, title, points, requirement, sort_order) VALUES ('1_5', 1, '주요조건 기준수립 및 현장 관리 상태 비교검증 실시', 50, '(로 브레이징)
   ▷ 가 용접 : 전류.전압.유량
   ▷ 주요조건 : 사양별 소재 장입량, 온도, 시간(콘베어속도). 용재량(동링.솔더)확인
   ▷ 로내 구간별 온도 실측관리    - 온도 타점기록계 관리 / 온도 프로파일 관리
   ▷ 로내 질소가스 비율 관리 기준 설정 및 준수상태
(수동 브레이징 용접)
   ▷ 용접 표준서 게시 (온도. 한도견본)
   ▷ 용접 작업자 인증 . 용접 검사로 보증
   ▷ 겹침 모재 적정틈새 유지 관리
   ▷ 용접조건 기준관리
    → 용접 조건 관리항목 : 가스 유량 경보장치 설치 미설치시 관리방안 수립 및 기준준수, 실행상태

※ 작업자 착용장갑에 의한 제품 오염(실오라기 등)으로 용접부 리크 발생이 없도록 점검', 4);
INSERT INTO sq_items (code, category_id, title, points, requirement, sort_order) VALUES ('2_1', 2, '수입검사 실시기준 수립 및 준수상태', 40, '- 검사협정서/기준서 체결상태(사급품은 1차 협력사가 체결한 검사협정서 사본 접수 및 동일 시료/주기로 검사 실시 필요)
        → 검사협정 체결이 어려울 시 검사기준서 수립으로 대체 (예: 대기업 공급 원재료,도금업종 등)
    - 외주품 입고 시 외주사 출하성적서 접수 및 수입검사 실측값 비교검증 여부
    - 원재료 M/SHEET 접수 시 물성 및 화학조성비 합/부 판단기준 명확화 수립
    - 입고 LOT와 출하검사 성적서내 LOT 일치성 확보여부(원소재의 경우 M/SHEET내 검사시료 LOT 일치성)
    - 검사협정서/기준서에 준한 일상검사/정기검사 실시상태
    - 용기/포장 적정성 (필요시 제전 비닐/박스, 이물질 유입 방지, 제품간 간섭 방지,
       물류 이동시 제품 훼손 방지,사양 식별, 오조립 방지, 이물질 유입방지, 체결부 좌면상태, 취급 용이성)
       및 습동부/매칭부 단품 치수검사 상태
    - 다 CAVITY 제품의 경우 CAVITY별 검사 기준 수립 및 준수 상태
      ※ 점검기준은 CAVITY 총 수량 고려 합리적인 점검주기 설정(일상/정기) 및 이행필요
          예) 일상 : 10 캐비티↓ : 전캐비티 검사,  11 캐비티↑ : 홀수일 Lot 홀수 캐비티/짝수일 Lot 짝수 캐비티 검사
               정기 : 전 캐비티 검사', 5);
INSERT INTO sq_items (code, category_id, title, points, requirement, sort_order) VALUES ('2_2', 2, '수입검사 누락방지 절차 수립(수입검사 대장 LIST 작성) 및 준수 상태', 30, '- 외주품 입고시 수입검사 마스터 관리 대장 작성을 통한 검사 누락 예방
